<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();require_admin('orders.oversee');$db=get_db();$id=(int)($_GET['id']??0);if($id>0){$order=$db->prepare('SELECT o.*,u.first_name,u.last_name,u.email,u.mobile FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=:id');$order->execute(['id'=>$id]);$order=$order->fetch();if(!$order)json_response(404,['success'=>false,'message'=>'Order not found.']);$groups=$db->prepare('SELECT g.*,v.display_name FROM vendor_order_groups g JOIN vendors v ON v.id=g.vendor_id WHERE g.order_id=:order');$groups->execute(['order'=>$id]);$order['groups']=$groups->fetchAll();json_response(200,['success'=>true,'order'=>$order]);}$status=trim((string)($_GET['status']??''));$stmt=$db->prepare('SELECT o.id,o.order_number,o.status,o.payment_status,o.total_amount,o.created_at,u.first_name,u.last_name,COUNT(g.id) vendor_count FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN vendor_order_groups g ON g.order_id=o.id WHERE (:status="" OR o.status=:status) GROUP BY o.id ORDER BY o.created_at DESC LIMIT 500');$stmt->execute(['status'=>$status]);json_response(200,['success'=>true,'orders'=>$stmt->fetchAll()]);
